<script setup>import{onMounted,ref}from'vue';import{aiCenterApi}from'../api';import SafeHtml from'../components/SafeHtml.vue';import SafeMarkdown from'../components/SafeMarkdown.vue';const page=ref(null),error=ref('');onMounted(async()=>{try{page.value=await aiCenterApi.content('VCP_INTRO')}catch(e){error.value=e.message}})</script><template><main class="vcp-page page-width"><header><router-link to="/ai-center">← AI Center</router-link><span>VCP · FUTURE RUNTIME</span></header><p v-if="error" class="form-error">{{error}}</p><article v-if="page"><h1>{{page.title}}</h1><p class="vcp-subtitle">{{page.subtitle}}</p><SafeMarkdown v-if="page.contentFormat==='MARKDOWN'" :content="page.contentBody"/><SafeHtml v-else :content="page.contentBody"/></article></main></template>
